transforms.post:
result.(
  $subjectListTypeId := $coalesce([subjectListTypeId, $$.rowData.subjectListTypeId]);
  ($exists($subjectListTypeId) and $isNilOrEmpty($lookup($subjectListTypeId & 'Id')) and 
  $isNilOrEmpty($$.rowData.($lookup($subjectListTypeId & 'Id')))) ? $throw('The subject type: "' & $subjectListTypeId & '" must be provided for this subject list type.') 
  : $ ~> | $ | 
    { 
      "productId": $not($subjectListTypeId = "product") ? null : $coalesce([productId, $$.rowData.productId]),
      "processId": $not($subjectListTypeId in ["process", "product"]) ? null : $coalesce([processId, $$.rowData.processId]),
      "workcenterId": $subjectListTypeId = "lotControl" ? null : $coalesce([workcenterId, $$.rowData.workcenterId]),
      "productProcessId": $not($subjectListTypeId = "productProcess") ? null : $coalesce([productProcessId, $$.rowData.productProcessId]),
      "lotControlId": $not($subjectListTypeId = "lotControl") ? null : $coalesce([lotControlId, $$.rowData.lotControlId])
    } |
)
